import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { ScentScene } from './scene';
import { MemoryDirector } from './director';

let scene: ScentScene | null = null;
let director: MemoryDirector | null = null;
let root: HTMLElement | null = null;
let memoryLine: HTMLElement | null = null;
let ratioLine: HTMLElement | null = null;
let stageLabel: HTMLElement | null = null;
let sealButton: HTMLButtonElement | null = null;
let sealedNote: HTMLElement | null = null;
let onSeal: (() => void) | null = null;

const makeMarkup = (): HTMLElement => {
  const element = document.createElement('main');
  element.className = 'scent-page';
  element.innerHTML = `
    <div class="scent-canvas-wash" aria-hidden="true"></div>
    <header class="scent-nav" aria-label="气味标本室导航">
      <a class="scent-mark" href="#opening">气味标本室 <span>NO. 083</span></a>
      <span class="scent-nav-note">一座私人嗅觉档案</span>
    </header>

    <div class="scent-scroll" id="opening">
      <section class="scent-hero" aria-labelledby="scent-title">
        <div class="scent-kicker">OLFACTORY MEMORY · 2026</div>
        <h1 id="scent-title">有些记忆，<br>先于语言回来。</h1>
        <p>将一次雨、一页旧书与一件晒暖的衬衫，保存成可以重新打开的气味标本。</p>
        <a class="scent-enter" href="#blend">进入这段记忆 <span aria-hidden="true">↓</span></a>
      </section>

      <section class="scent-blend" id="blend" aria-labelledby="blend-title">
        <div class="scent-panel">
          <div class="scent-kicker">MEMORY COMPOSITION</div>
          <h2 id="blend-title">记忆正在显影</h2>
          <p id="memory-line" aria-live="polite">雨停不久，玻璃上的雾气还没有散。</p>
          <div class="scent-ratios" id="ratio-line">雨后泥土 34 · 旧书纸张 33 · 晒过的棉布 33</div>
          <p class="scent-hint">移动指针或轻触画面，改变三种气味的混合比例。</p>
        </div>
        <div class="scent-index" aria-label="气味构成">
          <span><i class="soil"></i>雨后泥土</span>
          <span><i class="paper"></i>旧书纸张</span>
          <span><i class="cotton"></i>晒过的棉布</span>
        </div>
      </section>

      <section class="scent-final" aria-labelledby="final-title">
        <div class="scent-final-copy">
          <div class="scent-kicker" id="stage-label">SPECIMEN READY</div>
          <h2 id="final-title">把今天，<br>留给未来的你。</h2>
          <p>三层气味已经重新汇合。它会保留此刻的比例，也保留你为它停留的时间。</p>
          <button class="scent-seal" type="button">封存这段记忆</button>
          <div class="scent-sealed-note" aria-live="polite"></div>
        </div>
        <div class="scent-catalog" aria-label="标本信息">
          <span>采集地</span><b>一场雨后的房间</b>
          <span>保存状态</span><b>等待封存</b>
          <span>标本编号</span><b>SM–083</b>
        </div>
      </section>
    </div>`;
  return element;
};

startExperience(defineExperience({
  mount(context) {
    root = makeMarkup();
    context.container.appendChild(root);
    memoryLine = root.querySelector<HTMLElement>('#memory-line');
    ratioLine = root.querySelector<HTMLElement>('#ratio-line');
    stageLabel = root.querySelector<HTMLElement>('#stage-label');
    sealButton = root.querySelector<HTMLButtonElement>('.scent-seal');
    sealedNote = root.querySelector<HTMLElement>('.scent-sealed-note');

    director = new MemoryDirector(context.reducedMotion);
    scene = new ScentScene(context.canvas, context.quality, context.reducedMotion, context.viewport);

    onSeal = () => {
      if (sealButton === null || sealedNote === null) return;
      sealButton.textContent = '已封存';
      sealButton.disabled = true;
      sealedNote.textContent = '气味标本 SM–083 已收入你的私人档案。';
      root?.classList.add('is-sealed');
      scene?.setSealed(true);
    };
    sealButton?.addEventListener('click', onSeal);
  },

  update(frame) {
    if (scene === null || director === null) return;
    const state = director.sample(frame.progress, frame.pointer.x, frame.pointer.y, frame.elapsed);
    scene.render(state, frame.delta);

    if (memoryLine !== null) memoryLine.textContent = state.memoryText;
    if (ratioLine !== null) {
      ratioLine.textContent = `雨后泥土 ${Math.round(state.mix.soil * 100)} · 旧书纸张 ${Math.round(state.mix.paper * 100)} · 晒过的棉布 ${Math.round(state.mix.cotton * 100)}`;
    }
    if (stageLabel !== null) stageLabel.textContent = state.progress > 0.84 ? 'SPECIMEN READY' : 'MEMORY IN PROCESS';
    root?.style.setProperty('--clarity', state.clarity.toFixed(3));
    root?.style.setProperty('--story-progress', state.progress.toFixed(3));
  },

  resize(viewport) {
    scene?.resize(viewport);
  },

  dispose() {
    if (sealButton !== null && onSeal !== null) sealButton.removeEventListener('click', onSeal);
    scene?.dispose();
    scene = null;
    director = null;
    root?.remove();
    root = null;
    memoryLine = null;
    ratioLine = null;
    stageLabel = null;
    sealButton = null;
    sealedNote = null;
    onSeal = null;
  }
}));

export interface ScentMix {
  soil: number;
  paper: number;
  cotton: number;
}

export interface DirectedState {
  progress: number;
  formation: number;
  separation: number;
  resolution: number;
  clarity: number;
  cameraX: number;
  cameraY: number;
  focusX: number;
  focusY: number;
  mix: ScentMix;
  memoryText: string;
  elapsed: number;
  reducedMotion: boolean;
}

const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));
const smooth = (edge0: number, edge1: number, value: number): number => {
  const t = clamp01((value - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
};

export class MemoryDirector {
  private readonly reducedMotion: boolean;

  constructor(reducedMotion: boolean) {
    this.reducedMotion = reducedMotion;
  }

  sample(progressValue: number, pointerXValue: number, pointerYValue: number, elapsed: number): DirectedState {
    const progress = clamp01(progressValue);
    const pointerX = clamp01((pointerXValue + 1) * 0.5);
    const pointerY = clamp01((pointerYValue + 1) * 0.5);

    const formation = smooth(0.08, 0.44, progress);
    const separationIn = smooth(0.28, 0.55, progress);
    const separationOut = 1 - smooth(0.7, 0.93, progress);
    const separation = separationIn * separationOut;
    const resolution = smooth(0.72, 0.96, progress);

    const soilRaw = 0.24 + (1 - pointerY) * 0.34;
    const paperRaw = 0.24 + pointerX * 0.3;
    const cottonRaw = 0.24 + pointerY * 0.32 + (1 - pointerX) * 0.12;
    const total = soilRaw + paperRaw + cottonRaw;
    const mix: ScentMix = {
      soil: soilRaw / total,
      paper: paperRaw / total,
      cotton: cottonRaw / total
    };

    let memoryText = '雨停不久，玻璃上的雾气还没有散。';
    if (progress > 0.3) {
      if (mix.soil >= mix.paper && mix.soil >= mix.cotton) {
        memoryText = '湿土的气息更近了，像鞋底带回房间的一小片院子。';
      } else if (mix.paper >= mix.cotton) {
        memoryText = '纸页吸收了潮气，旧书柜在安静的午后慢慢打开。';
      } else {
        memoryText = '棉布还留着日光，像晾衣绳经过肩头的一阵暖风。';
      }
    }
    if (resolution > 0.78) memoryText = '泥土、纸张与棉布已经汇合，成为只属于今天的气味标本。';

    const motionScale = this.reducedMotion ? 0 : 1;
    return {
      progress,
      formation,
      separation,
      resolution,
      clarity: this.reducedMotion ? (progress < 0.32 ? 0.24 : progress < 0.76 ? 0.7 : 1) : smooth(0.03, 0.82, progress),
      cameraX: (pointerX - 0.5) * 0.18 * motionScale,
      cameraY: (pointerY - 0.5) * 0.1 * motionScale,
      focusX: pointerX,
      focusY: pointerY,
      mix,
      memoryText,
      elapsed,
      reducedMotion: this.reducedMotion
    };
  }
}

import * as THREE from 'three';
import type { DirectedState } from './director';

interface ViewportLike {
  width: number;
  height: number;
  dpr: number;
}

type ExperienceQuality = 'low' | 'balanced' | 'high';

const environmentVertex = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = vec4(position.xy, 0.0, 1.0);
  }
`;

const environmentFragment = `
  precision highp float;
  uniform sampler2D uRoomA;
  uniform sampler2D uRoomB;
  uniform float uHasA;
  uniform float uHasB;
  uniform float uBlend;
  uniform float uClarity;
  uniform float uAspect;
  uniform float uImageAspectA;
  uniform float uImageAspectB;
  uniform vec2 uFocus;
  varying vec2 vUv;

  vec2 coverUv(vec2 uv, float imageAspect) {
    vec2 scale = vec2(1.0);
    if (uAspect > imageAspect) scale.y = imageAspect / uAspect;
    else scale.x = uAspect / imageAspect;
    return (uv - 0.5) * scale + 0.5;
  }

  vec3 fallbackRoom(vec2 uv) {
    float wall = smoothstep(0.18, 0.82, uv.y);
    vec3 low = vec3(0.16, 0.135, 0.105);
    vec3 high = vec3(0.67, 0.61, 0.49);
    float windowLight = smoothstep(0.52, 0.9, uv.x) * smoothstep(0.12, 0.78, uv.y);
    return mix(low, high, wall * 0.7) + vec3(0.16, 0.13, 0.08) * windowLight;
  }

  void main() {
    vec2 uvA = coverUv(vUv, uImageAspectA);
    vec2 uvB = coverUv(vUv, uImageAspectB);
    vec3 base = fallbackRoom(vUv);
    vec3 roomA = texture2D(uRoomA, uvA).rgb;
    vec3 roomB = texture2D(uRoomB, uvB).rgb;
    vec3 a = mix(base, roomA, uHasA);
    vec3 b = mix(a, roomB, uHasB);
    vec3 color = mix(a, b, uBlend * 0.42);
    float local = 1.0 - smoothstep(0.08, 0.48, distance(vUv, uFocus));
    float haze = (1.0 - uClarity) * (0.16 - local * 0.055);
    color = mix(color, vec3(0.72, 0.69, 0.61), haze);
    color *= mix(0.68, 1.0, uClarity);
    color = mix(color, vec3(dot(color, vec3(0.299, 0.587, 0.114))), (1.0 - uClarity) * 0.28);
    float vignette = smoothstep(0.88, 0.28, distance(vUv, vec2(0.5)));
    color *= mix(0.74, 1.05, vignette);
    gl_FragColor = vec4(color, 1.0);
  }
`;

export class ScentScene {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene: THREE.Scene;
  private readonly camera: THREE.PerspectiveCamera;
  private readonly environmentScene: THREE.Scene;
  private readonly environmentCamera: THREE.Camera;
  private readonly environmentMaterial: THREE.ShaderMaterial;
  private readonly bottleGroup = new THREE.Group();
  private readonly layerGroup = new THREE.Group();
  private readonly bottleMaterial: THREE.MeshPhysicalMaterial;
  private readonly soilMaterial: THREE.MeshStandardMaterial;
  private readonly paperMaterial: THREE.MeshStandardMaterial;
  private readonly cottonMaterial: THREE.MeshStandardMaterial;
  private readonly sealMaterial: THREE.MeshStandardMaterial;
  private readonly geometries: THREE.BufferGeometry[] = [];
  private readonly textures: THREE.Texture[] = [];
  private readonly loader: THREE.TextureLoader;
  private readonly reducedMotion: boolean;
  private sealed = false;
  private width = 1;
  private height = 1;

  constructor(canvas: HTMLCanvasElement, quality: ExperienceQuality, reducedMotion: boolean, viewport: ViewportLike) {
    this.reducedMotion = reducedMotion;
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: quality !== 'low', alpha: true, powerPreference: quality === 'high' ? 'high-performance' : 'default' });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 0.92;
    this.renderer.setClearColor(0x30291f, 1);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(34, 1, 0.1, 40);
    this.camera.position.set(0, 0.2, 7.2);

    this.environmentScene = new THREE.Scene();
    this.environmentCamera = new THREE.Camera();
    const emptyTexture = this.createFallbackTexture();
    this.environmentMaterial = new THREE.ShaderMaterial({
      vertexShader: environmentVertex,
      fragmentShader: environmentFragment,
      depthTest: false,
      depthWrite: false,
      uniforms: {
        uRoomA: { value: emptyTexture },
        uRoomB: { value: emptyTexture },
        uHasA: { value: 0 },
        uHasB: { value: 0 },
        uBlend: { value: 0 },
        uClarity: { value: 0 },
        uAspect: { value: 1 },
        uImageAspectA: { value: 1.5 },
        uImageAspectB: { value: 1.5 },
        uFocus: { value: new THREE.Vector2(0.5, 0.5) }
      }
    });
    const environmentGeometry = new THREE.PlaneGeometry(2, 2);
    this.geometries.push(environmentGeometry);
    this.environmentScene.add(new THREE.Mesh(environmentGeometry, this.environmentMaterial));

    this.loader = new THREE.TextureLoader();
    this.loader.setCrossOrigin('anonymous');
    if (quality !== 'low') {
      this.loadEnvironment('/creative-assets/r20-scent-memory/scent-memory-environment-v1.png', 'uRoomA', 'uHasA', 'uImageAspectA');
    }

    this.bottleMaterial = new THREE.MeshPhysicalMaterial({ color: 0xf4efe4, roughness: 0.08, transmission: quality === 'low' ? 0.58 : 0.94, thickness: 0.12, transparent: true, opacity: 0.22, depthWrite: false, ior: 1.46, clearcoat: 1, side: THREE.DoubleSide });
    this.soilMaterial = new THREE.MeshStandardMaterial({ color: 0x554633, roughness: 0.92, metalness: 0, transparent: true, opacity: 0.34, depthWrite: false });
    this.paperMaterial = new THREE.MeshStandardMaterial({ color: 0xb99c6a, roughness: 0.77, metalness: 0, transparent: true, opacity: 0.25, depthWrite: false });
    this.cottonMaterial = new THREE.MeshStandardMaterial({ color: 0xe4d8ba, roughness: 1, metalness: 0, transparent: true, opacity: 0.22, depthWrite: false });
    this.sealMaterial = new THREE.MeshStandardMaterial({ color: 0x4a3828, roughness: 0.9, transparent: true, opacity: 0.16, depthWrite: false });

    this.buildSpecimen();
    this.addLighting();
    this.resize(viewport);
  }

  private createFallbackTexture(): THREE.DataTexture {
    const pixels = new Uint8Array([80, 70, 55, 255, 164, 148, 116, 255, 57, 49, 39, 255, 126, 112, 88, 255]);
    const texture = new THREE.DataTexture(pixels, 2, 2, THREE.RGBAFormat);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.needsUpdate = true;
    this.textures.push(texture);
    return texture;
  }

  private loadEnvironment(uri: string, samplerName: string, presenceName: string, aspectName: string): void {
    this.loader.load(uri, (texture) => {
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.magFilter = THREE.LinearFilter;
      this.textures.push(texture);
      this.environmentMaterial.uniforms[samplerName].value = texture;
      this.environmentMaterial.uniforms[presenceName].value = 1;
      const image = texture.image as { width?: number; height?: number };
      if (typeof image.width === 'number' && typeof image.height === 'number' && image.height > 0) {
        this.environmentMaterial.uniforms[aspectName].value = image.width / image.height;
      }
    }, undefined, () => {
      this.environmentMaterial.uniforms[presenceName].value = 0;
    });
  }

  private buildSpecimen(): void {
    const profile = [
      new THREE.Vector2(0.02, -1.55), new THREE.Vector2(0.74, -1.5), new THREE.Vector2(0.88, -1.28),
      new THREE.Vector2(0.9, 0.62), new THREE.Vector2(0.78, 0.9), new THREE.Vector2(0.42, 1.12),
      new THREE.Vector2(0.35, 1.42), new THREE.Vector2(0.02, 1.45)
    ];
    const bottleGeometry = new THREE.LatheGeometry(profile, 48);
    this.geometries.push(bottleGeometry);
    const bottle = new THREE.Mesh(bottleGeometry, this.bottleMaterial);
    bottle.renderOrder = 4;
    this.bottleGroup.add(bottle);

    const neckGeometry = new THREE.CylinderGeometry(0.36, 0.36, 0.38, 32);
    const sealGeometry = new THREE.CylinderGeometry(0.39, 0.35, 0.38, 32);
    this.geometries.push(neckGeometry, sealGeometry);
    const neck = new THREE.Mesh(neckGeometry, this.bottleMaterial);
    neck.position.y = 1.48;
    const seal = new THREE.Mesh(sealGeometry, this.sealMaterial);
    seal.position.y = 1.78;
    this.bottleGroup.add(neck, seal);

    const layerGeometry = new THREE.CylinderGeometry(0.56, 0.62, 0.22, 40);
    this.geometries.push(layerGeometry);
    const soil = new THREE.Mesh(layerGeometry, this.soilMaterial);
    const paper = new THREE.Mesh(layerGeometry, this.paperMaterial);
    const cotton = new THREE.Mesh(layerGeometry, this.cottonMaterial);
    soil.name = 'soil';
    paper.name = 'paper';
    cotton.name = 'cotton';
    this.layerGroup.add(soil, paper, cotton);
    this.bottleGroup.add(this.layerGroup);
    this.bottleGroup.position.set(0, -0.15, 0);
    this.scene.add(this.bottleGroup);
  }

  private addLighting(): void {
    this.scene.add(new THREE.HemisphereLight(0xf1e2c2, 0x33291e, 1.8));
    const key = new THREE.DirectionalLight(0xffe4b5, 4.2);
    key.position.set(4, 5, 5);
    this.scene.add(key);
    const rim = new THREE.DirectionalLight(0x9caa91, 1.2);
    rim.position.set(-4, 1, 2);
    this.scene.add(rim);
  }

  setSealed(sealed: boolean): void {
    this.sealed = sealed;
  }

  render(state: DirectedState, delta: number): void {
    const uniforms = this.environmentMaterial.uniforms;
    uniforms.uBlend.value = state.formation;
    uniforms.uClarity.value = state.clarity;
    (uniforms.uFocus.value as THREE.Vector2).set(state.focusX, 1 - state.focusY);

    const portrait = this.width / this.height < 0.72;
    const baseX = portrait ? 0.22 : 0;
    const baseY = portrait ? -0.65 : -0.1;
    this.bottleGroup.position.x = baseX + state.cameraX;
    this.bottleGroup.position.y = baseY - state.cameraY;

    const hazeScale = portrait
      ? 0.46 + state.formation * 0.06
      : 0.68 + state.formation * 0.1;
    this.bottleGroup.scale.setScalar(hazeScale);
    this.bottleMaterial.opacity = 0.12 + state.clarity * 0.16;
    this.bottleMaterial.roughness = 0.2 - state.clarity * 0.12;

    const layers = this.layerGroup.children;
    const soil = layers[0];
    const paper = layers[1];
    const cotton = layers[2];
    const spread = state.separation * (portrait ? 0.26 : 0.38);
    const settle = state.resolution;

    soil.position.set(-spread, -0.62 + settle * 0.1, spread * 0.08);
    paper.position.set(0, -0.08, spread * 0.22);
    cotton.position.set(spread, 0.54 - settle * 0.1, spread * 0.08);
    soil.rotation.z = -spread * 0.14;
    paper.rotation.z = spread * 0.05;
    cotton.rotation.z = spread * 0.13;

    soil.scale.y = 0.55 + state.mix.soil * 0.35;
    paper.scale.y = 0.55 + state.mix.paper * 0.35;
    cotton.scale.y = 0.55 + state.mix.cotton * 0.35;

    const calm = state.resolution > 0.8 || this.reducedMotion || this.sealed;
    if (!calm) {
      const restrainedBreath = Math.sin(state.elapsed * 0.55) * 0.008 * state.separation;
      this.layerGroup.rotation.y = restrainedBreath;
    } else {
      this.layerGroup.rotation.y *= Math.max(0, 1 - delta * 5);
    }

    this.camera.position.x = state.cameraX * 0.5;
    this.camera.position.y = 0.2 - state.cameraY * 0.4;
    this.camera.lookAt(baseX * 0.12, 0.08, 0);

    this.renderer.autoClear = true;
    this.renderer.render(this.environmentScene, this.environmentCamera);
    this.renderer.autoClear = false;
    this.renderer.clearDepth();
    this.renderer.render(this.scene, this.camera);
    this.renderer.autoClear = true;
  }

  resize(viewport: ViewportLike): void {
    this.width = Math.max(1, viewport.width);
    this.height = Math.max(1, viewport.height);
    this.renderer.setPixelRatio(Math.min(viewport.dpr, 2));
    this.renderer.setSize(this.width, this.height, false);
    this.camera.aspect = this.width / this.height;
    this.camera.updateProjectionMatrix();
    this.environmentMaterial.uniforms.uAspect.value = this.width / this.height;
  }

  dispose(): void {
    for (const geometry of this.geometries) geometry.dispose();
    this.environmentMaterial.dispose();
    this.bottleMaterial.dispose();
    this.soilMaterial.dispose();
    this.paperMaterial.dispose();
    this.cottonMaterial.dispose();
    this.sealMaterial.dispose();
    for (const texture of this.textures) texture.dispose();
    this.scene.clear();
    this.environmentScene.clear();
    this.renderer.dispose();
  }
}

* { box-sizing: border-box; }
html { margin: 0; max-width: 100%; scroll-behavior: smooth; background: #31291f; }
body { margin: 0; max-width: 100%; overflow-x: clip; color: #f0e9dc; background: #31291f; font-family: "Noto Serif SC", "Songti SC", Georgia, serif; }
canvas { position: fixed; inset: 0; width: 100%; height: 100%; display: block; z-index: 0; }
button, a { font: inherit; }
.scent-page { --clarity: 0; --story-progress: 0; position: relative; min-height: 340vh; max-width: 100%; isolation: isolate; }
.scent-canvas-wash { position: fixed; inset: 0; z-index: 1; pointer-events: none; background: linear-gradient(90deg, rgba(34,28,21,.74) 0%, rgba(34,28,21,.28) 48%, rgba(34,28,21,.08) 100%), linear-gradient(0deg, rgba(28,23,18,.48), transparent 34%); opacity: calc(.96 - var(--clarity) * .36); }
.scent-nav { position: fixed; top: 0; left: 0; z-index: 5; width: 100%; display: flex; justify-content: space-between; align-items: center; padding: 24px clamp(20px, 5vw, 72px); font-family: system-ui, sans-serif; font-size: 11px; letter-spacing: .13em; text-transform: uppercase; }
.scent-mark { color: inherit; text-decoration: none; font-weight: 650; }
.scent-mark span { margin-left: 10px; color: #d4b784; font-weight: 400; }
.scent-nav-note { color: rgba(240,233,220,.66); }
.scent-scroll { position: relative; z-index: 2; min-height: 340vh; max-width: 100%; }
.scent-hero, .scent-blend, .scent-final { min-height: 100vh; padding: clamp(88px, 12vh, 138px) clamp(20px, 7vw, 104px) clamp(48px, 8vh, 96px); }
.scent-hero { display: flex; flex-direction: column; justify-content: center; align-items: flex-start; width: min(720px, 58vw); }
.scent-kicker { margin-bottom: 20px; color: #dfc89f; font-family: system-ui, sans-serif; font-size: 10px; font-weight: 650; letter-spacing: .2em; }
.scent-hero h1 { max-width: 690px; margin: 0; font-size: clamp(42px, 6.3vw, 88px); line-height: 1.08; font-weight: 450; letter-spacing: -.045em; text-wrap: balance; }
.scent-hero p { max-width: 500px; margin: 28px 0 0; color: rgba(240,233,220,.78); font-size: clamp(15px, 1.35vw, 19px); line-height: 1.9; }
.scent-enter { display: inline-flex; gap: 18px; align-items: center; margin-top: 34px; padding: 12px 0; border-bottom: 1px solid rgba(240,233,220,.5); color: #f0e9dc; text-decoration: none; font-family: system-ui, sans-serif; font-size: 13px; letter-spacing: .08em; }
.scent-blend { min-height: 125vh; display: flex; justify-content: space-between; align-items: center; gap: 40px; }
.scent-panel { width: min(500px, 44vw); padding: 34px 38px; border-left: 1px solid rgba(228,211,181,.48); background: linear-gradient(90deg, rgba(41,34,26,.62), rgba(41,34,26,.08)); backdrop-filter: blur(8px); }
.scent-panel h2, .scent-final h2 { margin: 0; font-size: clamp(34px, 4.4vw, 64px); line-height: 1.12; font-weight: 450; letter-spacing: -.035em; }
.scent-panel > p { min-height: 4.2em; margin: 24px 0 0; color: rgba(244,237,224,.88); font-size: 16px; line-height: 1.95; }
.scent-ratios { margin-top: 22px; color: #d9bd8d; font-family: system-ui, sans-serif; font-size: 11px; line-height: 1.8; letter-spacing: .08em; }
.scent-panel .scent-hint { min-height: 0; margin-top: 10px; color: rgba(240,233,220,.54); font-family: system-ui, sans-serif; font-size: 11px; line-height: 1.6; }
.scent-index { align-self: flex-end; display: grid; gap: 11px; margin-bottom: 8vh; color: rgba(240,233,220,.74); font-family: system-ui, sans-serif; font-size: 11px; letter-spacing: .08em; }
.scent-index span { display: flex; align-items: center; gap: 10px; }
.scent-index i { width: 22px; height: 3px; display: inline-block; }
.scent-index .soil { background: #65523b; }
.scent-index .paper { background: #c1a474; }
.scent-index .cotton { background: #e4d8ba; }
.scent-final { min-height: 115vh; display: flex; align-items: center; justify-content: space-between; gap: 64px; background: linear-gradient(90deg, rgba(38,31,24,.82), rgba(38,31,24,.2) 56%, transparent); }
.scent-final-copy { width: min(550px, 48vw); }
.scent-final-copy > p { max-width: 460px; margin: 26px 0 0; color: rgba(240,233,220,.76); font-size: 16px; line-height: 1.9; }
.scent-seal { min-width: 190px; min-height: 52px; margin-top: 34px; padding: 14px 25px; border: 1px solid #d7bd91; border-radius: 0; color: #31291f; background: #dfc89f; cursor: pointer; font-family: system-ui, sans-serif; font-size: 14px; font-weight: 650; letter-spacing: .08em; transition: background-color .25s ease, color .25s ease; }
.scent-seal:hover, .scent-seal:focus-visible { color: #f0e9dc; background: #8b6843; outline: 2px solid rgba(240,233,220,.5); outline-offset: 3px; }
.scent-seal:disabled { cursor: default; color: #e9decc; background: #66513b; }
.scent-sealed-note { min-height: 22px; margin-top: 14px; color: #d9bd8d; font-family: system-ui, sans-serif; font-size: 12px; }
.scent-catalog { display: grid; grid-template-columns: auto minmax(150px, 230px); gap: 14px 28px; align-self: flex-end; margin-bottom: 6vh; padding: 24px 0; border-top: 1px solid rgba(240,233,220,.28); border-bottom: 1px solid rgba(240,233,220,.28); font-family: system-ui, sans-serif; font-size: 11px; }
.scent-catalog span { color: rgba(240,233,220,.48); }
.scent-catalog b { color: rgba(240,233,220,.84); font-weight: 500; }
.is-sealed .scent-catalog b:nth-of-type(2) { color: #dfc89f; }
@media (max-width: 720px) {
  .scent-page, .scent-scroll { min-height: 360vh; }
  .scent-nav { padding: 18px 20px; }
  .scent-nav-note { display: none; }
  .scent-hero, .scent-blend, .scent-final { padding: 84px 20px 42px; }
  .scent-hero { width: 100%; min-height: 100svh; justify-content: flex-start; padding-top: 17svh; }
  .scent-hero h1 { max-width: 350px; font-size: clamp(40px, 13.2vw, 58px); line-height: 1.09; }
  .scent-hero p { max-width: 330px; margin-top: 22px; font-size: 15px; line-height: 1.75; }
  .scent-enter { margin-top: 22px; min-height: 44px; }
  .scent-canvas-wash { background: linear-gradient(180deg, rgba(34,28,21,.62) 0%, rgba(34,28,21,.15) 44%, rgba(34,28,21,.7) 100%); }
  .scent-blend { min-height: 135svh; flex-direction: column; align-items: stretch; justify-content: flex-end; padding-bottom: 11vh; }
  .scent-panel { width: 100%; padding: 26px 22px; background: rgba(41,34,26,.68); }
  .scent-panel h2, .scent-final h2 { font-size: clamp(34px, 10.5vw, 48px); }
  .scent-panel > p { font-size: 14px; }
  .scent-index { align-self: flex-start; margin: 0 0 0 22px; }
  .scent-final { min-height: 125svh; flex-direction: column; justify-content: flex-end; align-items: stretch; padding-bottom: 8vh; background: linear-gradient(0deg, rgba(38,31,24,.93), rgba(38,31,24,.14) 78%, transparent); }
  .scent-final-copy { width: 100%; }
  .scent-final-copy > p { font-size: 14px; }
  .scent-seal { width: 100%; min-height: 54px; }
  .scent-catalog { align-self: stretch; margin: 8px 0 0; grid-template-columns: 82px 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .scent-seal { transition: none; }
  .scent-panel { backdrop-filter: none; }
}
